#!/usr/bin/env node
/**
 * The server's code generation (`generate`), and its check (`--check`,
 * `check-generate`): runs the module's `//go:generate` directives, packages in
 * parallel, in a copy of the working tree, then brings the working tree's
 * generated files to what that run produced, or with `--check` fails when
 * they differ.
 *
 * In a copy, because generation deletes and rewrites files every other task
 * reads: in place, a task beside it (or a failure half-way) would see half a
 * tree. The copy holds the working tree's files (tracked, and untracked ones
 * git does not ignore) minus their generated files, because generators only
 * ever write and never retract: when a directive changes destination, or an
 * interface stops being mocked, the old file would stay on disk and stay
 * committed — still compiling, still imported, quietly wrong. So what comes
 * back is exactly what the directives produce, and a file that does not come
 * back is one nothing generates any more. The deletion is guarded twice: the
 * globs are file-precise (scripts/generated-outputs.mjs), and every file must
 * carry a "generated by … DO NOT EDIT" marker; a file matching a glob without
 * one is reported and kept. Back in the working tree only the files that
 * differ change, each in one rename, so a tree that is already right is not
 * touched. The generated files are committed, so no task waits for
 * `generate`: it is the tool a person runs after changing a source, and
 * `check-generate` fails when they forgot.
 *
 * `go generate ./...` is strictly serial, and the directives are almost pure
 * per-invocation overhead — mockgen spends ~800ms type-loading a package
 * whether it mocks one interface or twenty. Running the four mockgen packages
 * concurrently collapses 4.3s into 1.4s, and the five enumer ones 2.2s into
 * 1.6s.
 *
 * That is ~21% end to end (6.4s against 8.1s), not the 4x the arithmetic
 * suggests, because `./api` is a serial chain and now the larger half of the
 * run: `gen_openapi_errors` type-loads the whole module to infer error sets,
 * and 2.6s of the 3.5s api phase is that one analysis. It parallelizes against
 * nothing — see the ordering below — so it sets the floor. Worth knowing
 * before optimizing the phases around it.
 *
 * The ordering that matters is a phase boundary, not a package-internal one.
 * `./api` runs alone between the two `rest` phases, for a reason on each side:
 *
 *   - after enumer, because `api/cmd/gen_openapi_errors` type-loads
 *     `./internal/...` to infer each handler's error set, and `internal/domain`
 *     does not type-check until its `*_enumer.go` files exist.
 *   - before mockgen, because that same load — and `gen_error_schemas` parsing
 *     `internal/domain` source — must observe those trees at rest, rather than
 *     while mockgen is writing `.go` files into them.
 *
 * Within a package `go generate` keeps directives in file order, which is what
 * keeps api's own chain (error schemas -> openapi errors -> ogen) intact.
 *
 * That chain closes a cycle on a pruned tree — the analysis needs the stubs
 * ogen writes at the end of it — which `api/cmd/gen_openapi_errors` breaks from
 * the inside, by generating a bootstrap pass of them for itself. Nothing about it is
 * this runner's business; bare `go generate ./...` gets the same treatment.
 *
 * Today the mockgen race would be benign — enumer writes via a same-directory
 * `os.Rename` and its temp files carry no `.go` suffix, and the generated
 * `*_enumer.go` files declare no error constructors — but that is a property
 * of the current tools, not an invariant anyone declared. The phase boundary
 * costs ~0.3s and removes the class.
 */
import { createHash } from "node:crypto";
import { availableParallelism, tmpdir } from "node:os";
import {
  copyFileSync,
  existsSync,
  mkdirSync,
  readdirSync,
  readFileSync,
  renameSync,
  rmSync,
  symlinkSync,
  unlinkSync,
} from "node:fs";
import { dirname, join, relative } from "node:path";
import { fileURLToPath } from "node:url";

import { isDirectRun, run, runCapture } from "./dev-process.mjs";
import { collectGeneratedFiles } from "./generated-outputs.mjs";
import { mapAll } from "./map-all.mjs";
import { serverModuleRoot } from "./server-build.mjs";

const REPO_ROOT = fileURLToPath(new URL("..", import.meta.url));
// The Go module; every directive the server generates lives below it.
const ROOT = serverModuleRoot(REPO_ROOT);

// Never hold Go sources, and walking them dwarfs the rest of discovery.
// `.claude` holds agent worktrees, `.go` a local module cache and `vendor` a
// local `go mod vendor` copy; all are local-only and full of directives that
// are not this module's.
const SKIP_DIRS = new Set([
  "node_modules",
  ".git",
  ".claude",
  ".codex",
  ".cursor",
  ".agents",
  ".opencode",
  ".vercel",
  ".go",
  "vendor",
  "dist",
  "target",
  ".next",
  ".turbo",
  "testdata",
  "tmp",
  ".tmp",
]);

// Runs alone, between the enumer and mockgen phases — see the module comment.
const ORDERED_PACKAGE = "api";

// Go 1.27 turns the jsonv2 experiment on by default, which makes
// encoding/json's Marshaler and Unmarshaler type aliases. ogen resolves an
// x-ogen-type by asserting *types.Named on them and panics on an alias
// (ogen-go/ogen#1747), so the api package generates with the experiment off.
// A caller's own experiments are kept; the later entry wins. Drop this once an
// ogen release carries the fix. A bare `go generate ./...` under Go 1.27 needs
// the same variable set by hand.
const ORDERED_PACKAGE_ENV = {
  ...process.env,
  GOEXPERIMENT: [process.env.GOEXPERIMENT, "nojsonv2"].filter(Boolean).join(","),
};

const DIRECTIVE = /^\/\/go:generate .*$/gm;

/** Runs every directive of the Go module at `moduleRoot`, in place. */
export async function goGenerate({ moduleRoot = ROOT, log = console.log } = {}) {
  const packages = findGeneratePackages(moduleRoot);
  assertEveryDirectiveHasAPhase(packages);

  const dirs = [...packages.keys()];
  const ordered = dirs.filter((dir) => dir === ORDERED_PACKAGE);
  const rest = dirs.filter((dir) => dir !== ORDERED_PACKAGE);

  // enumer writes .go files *into* a package; mockgen and the api generators
  // type-load packages. So every enumer directive must finish before any of
  // them runs, or a package whose generated methods do not exist yet is loaded
  // and the load fails.
  //
  // Under `go generate ./...` that ordering comes for free, because the
  // mockgen directives live in the mock subpackages and `./...` walks packages
  // in import-path order. This runner deliberately ignores that order — it
  // runs packages concurrently — so it has to restate the constraint as an
  // explicit barrier. Both paths generate from a tree with no generated files
  // in it at all, as every run here does after its prune.
  //
  // The barrier is global rather than per-package on purpose: internal/service
  // imports internal/domain, so its mockgen needs *domain's* enumer output,
  // not just its own package's.
  await runPhase(moduleRoot, rest, ENUMER_PHASE, log);

  for (const dir of ordered) {
    log(`--- ${dir}`);
    await run("go", ["generate", "."], { cwd: join(moduleRoot, dir), env: ORDERED_PACKAGE_ENV });
  }

  await runPhase(moduleRoot, rest, MOCKGEN_PHASE, log);
}

// `go generate -run` filters directives by matching against the command text,
// so between them these two decide what this runner runs at all — see
// assertEveryDirectiveHasAPhase.
const ENUMER_PHASE = { name: "enumer", filter: "enumer" };
const MOCKGEN_PHASE = { name: "mockgen", filter: "mockgen" };
const PHASES = [ENUMER_PHASE, MOCKGEN_PHASE];

/**
 * Fails when a directive belongs to no phase.
 *
 * Every phase runs `go generate -run <filter>`, so a directive matching neither
 * filter — a `stringer` added next year — is not deferred to some later phase,
 * it is never run. Silently: `check-generate` cannot see the drift either,
 * because the output it would compare against simply never comes into
 * existence, while bare `go generate ./...` would have produced it.
 *
 * The files were read to find the directories anyway, so the check is free.
 */
function assertEveryDirectiveHasAPhase(packages) {
  const unclaimed = [];
  for (const [dir, directives] of packages) {
    // Runs unfiltered, as its whole chain in file order.
    if (dir === ORDERED_PACKAGE) {
      continue;
    }
    for (const directive of directives) {
      if (!PHASES.some((phase) => new RegExp(phase.filter).test(directive))) {
        unclaimed.push(`  ${dir}: ${directive}`);
      }
    }
  }

  if (unclaimed.length > 0) {
    const filters = PHASES.map((phase) => `-run ${phase.filter}`).join(", ");
    throw new Error(
      `No generation phase claims these //go:generate directives:\n${unclaimed.join("\n")}\n\n` +
        `This runner only ever runs ${filters}, so a directive matching none of them never\n` +
        `runs here — and never shows up as drift, because its output is never written.\n` +
        `Add a phase for it in scripts/go-generate.mjs, ordered against the existing ones.`,
    );
  }
}

async function runPhase(moduleRoot, dirs, phase, log) {
  const limit = Math.max(1, Math.min(availableParallelism(), dirs.length));
  await mapAll(
    dirs,
    async (dir) => {
      // Buffered per package so concurrent generators never interleave. On
      // failure runCapture folds both streams into the thrown error's message.
      const { stdout, stderr } = await runCapture("go", ["generate", "-run", phase.filter, "."], {
        cwd: join(moduleRoot, dir),
      });
      const output = `${stdout}${stderr}`.trim();
      // Most packages have nothing to do in a given phase; only say so when
      // something actually ran.
      if (output) {
        log(`--- ${dir} (${phase.name})\n${output}`);
      }
    },
    limit,
  );
}

/**
 * Every directory holding a `//go:generate` directive, module-relative, mapped
 * to the directives it holds.
 *
 * Each is generated with `go generate .` rather than `./...`, so a directory
 * whose subdirectories also hold directives (`internal/instrumentation` over
 * `zotel` and `zlog`) does not run them a second time — which would otherwise
 * put two processes on the same output file concurrently.
 */
export function findGeneratePackages(root = ROOT) {
  const found = new Map();

  const walk = (dir) => {
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
      if (entry.isDirectory()) {
        // A nested module owns its generation; test fixtures are not packages
        // whose directives the root build should execute.
        if (!SKIP_DIRS.has(entry.name) && !existsSync(join(dir, entry.name, "go.mod"))) {
          walk(join(dir, entry.name));
        }
        continue;
      }
      if (!entry.name.endsWith(".go") || entry.name.endsWith("_test.go")) {
        continue;
      }
      const directives = readFileSync(join(dir, entry.name), "utf8").match(DIRECTIVE);
      if (!directives) {
        continue;
      }
      const pkg = relative(root, dir);
      found.set(pkg, [...(found.get(pkg) ?? []), ...directives]);
    }
  };

  walk(root);
  return new Map([...found].sort(([a], [b]) => a.localeCompare(b)));
}

/** Deletes the marked generated files; reports the unmarked ones it keeps. */
function deleteGeneratedFiles(root, log) {
  const { generated, unmarked } = collectGeneratedFiles(root);
  for (const rel of generated) {
    rmSync(join(root, rel));
  }
  if (unmarked.length > 0) {
    // Not fatal: the file may be hand-written and wrongly matched, which is
    // exactly the case the marker check exists to protect.
    log(`kept ${unmarked.length} file(s) matching an output glob without a generated marker:`);
    for (const rel of unmarked) {
      log(`  ${rel}`);
    }
    log("Check whether the globs in scripts/generated-outputs.mjs are too broad.");
  }
}

/**
 * Generates into a copy of the working tree at `copy` and returns how the
 * working tree's generated files differ from what came back. The copy's path
 * stays the same from run to run: Go keys its build cache by the package
 * directory, so the generators' own packages compile once, not every run.
 */
async function generateInCopy(copy, log) {
  rmSync(copy, { recursive: true, force: true });
  const { stdout } = await runCapture(
    "git",
    ["ls-files", "-z", "--cached", "--others", "--exclude-standard"],
    { cwd: REPO_ROOT },
  );
  for (const rel of stdout.split("\0")) {
    // A tracked file deleted in the working tree is listed but gone.
    if (rel && existsSync(join(REPO_ROOT, rel))) {
      mkdirSync(dirname(join(copy, rel)), { recursive: true });
      copyFileSync(join(REPO_ROOT, rel), join(copy, rel));
    }
  }
  symlinkSync(join(REPO_ROOT, "node_modules"), join(copy, "node_modules"), "dir");

  deleteGeneratedFiles(copy, log);
  await goGenerate({ moduleRoot: serverModuleRoot(copy), log });

  const produced = collectGeneratedFiles(copy).generated;
  const kept = new Set(produced);
  return {
    changed: produced.filter(
      (rel) =>
        !existsSync(join(REPO_ROOT, rel)) ||
        !readFileSync(join(REPO_ROOT, rel)).equals(readFileSync(join(copy, rel))),
    ),
    orphaned: collectGeneratedFiles(REPO_ROOT).generated.filter((rel) => !kept.has(rel)),
  };
}

/** Writes each changed file in one rename, then removes the orphans. */
function applyToWorkingTree(copy, { changed, orphaned }) {
  for (const rel of changed) {
    const target = join(REPO_ROOT, rel);
    const staged = `${target}.generating`;
    mkdirSync(dirname(target), { recursive: true });
    copyFileSync(join(copy, rel), staged);
    renameSync(staged, target);
  }
  for (const rel of orphaned) {
    rmSync(join(REPO_ROOT, rel));
  }
}

if (isDirectRun(import.meta.url)) {
  const check = process.argv.includes("--check");
  const copy = join(
    tmpdir(),
    "zitadel-generate",
    createHash("sha256").update(REPO_ROOT).digest("hex").slice(0, 12),
    check ? "check" : "generate",
  );
  try {
    const differences = await generateInCopy(copy, console.log);
    const { changed, orphaned } = differences;
    if (check) {
      if (changed.length > 0) {
        console.error("Generated files that differ from what generation produces:");
        for (const rel of changed) console.error(`  ${rel}`);
      }
      if (orphaned.length > 0) {
        console.error("Generated files that nothing generates any more:");
        for (const rel of orphaned) console.error(`  ${rel}`);
      }
      if (changed.length > 0 || orphaned.length > 0) {
        console.error("");
        console.error("Run `turbo run generate --filter=@zitadel/server` and commit the result.");
        process.exitCode = 1;
      }
    } else {
      applyToWorkingTree(copy, differences);
      console.log(`generate: ${changed.length} file(s) written, ${orphaned.length} removed`);
    }
  } catch (error) {
    // runCapture folds the generator's own stdout/stderr into the message; a
    // Node stack trace on top of it only buries the line that explains the
    // failure.
    console.error(error.message);
    console.error("");
    console.error(
      "Generation failed in a copy of the working tree; the working tree is unchanged.",
    );
    process.exitCode = 1;
  } finally {
    // Unlink first, so removing the copy never reaches the real node_modules.
    try {
      unlinkSync(join(copy, "node_modules"));
    } catch {}
    rmSync(copy, { recursive: true, force: true });
  }
}
